void EventBus::dispatch() {
  int processed = 0;
  while (!queue_.empty()) {
    if (++processed > MAX_EVENTS_PER_FRAME) {
      log("possible event feedback loop");
      break;
    }
    Event e = queue_.pop();
    deliver(e);
  }
}

struct PathRequest {
  EntityId unit;    // who asked (multiple writers)
  Vec2 from, to;
  uint32_t requestSerial;  // lets the unit ignore stale results
};

class PathJobQueue {
public:
  void post(std::unique_ptr<PathRequest> req) {
    std::lock_guard<std::mutex> lock(mutex_);
    jobs_.push_back(std::move(req));
    cv_.notify_one();  // wake exactly one worker
  }
  std::unique_ptr<PathRequest> take() {
    std::unique_lock<std::mutex> lock(mutex_);
    cv_.wait(lock, [this] { return !jobs_.empty(); });
    auto req = std::move(jobs_.front());
    jobs_.pop_front();
    return req;
  }
private:
  std::deque<std::unique_ptr<PathRequest>> jobs_;
  std::mutex mutex_;
  std::condition_variable cv_;
};
